import Handlebars from "handlebars";
import * as fs from "fs";
import * as path from "path";

export interface TemplateContext {
  page?: Record<string, unknown>;
  pages?: Record<string, unknown>[];
  site?: Record<string, unknown>;
  tags?: Record<string, unknown>[];
  content?: string;
  [key: string]: unknown;
}

export class TemplateEngine {
  private templates: Map<string, Handlebars.TemplateDelegate> = new Map();
  private partials: Map<string, Handlebars.TemplateDelegate> = new Map();
  private rawTemplates: Map<string, string> = new Map();
  private templateDir: string;
  private defaultLayout = "default";

  constructor(templateDir: string) {
    this.templateDir = templateDir;
  }

  load(): void {
    if (!fs.existsSync(this.templateDir)) {
      return;
    }

    this.loadPartials();
    this.loadTemplates();
  }

  private loadPartials(): void {
    const partialsDir = path.join(this.templateDir, "partials");
    if (!fs.existsSync(partialsDir)) return;

    const files = this.readDirRecursive(partialsDir);
    for (const file of files) {
      const name = file
        .replace(partialsDir + path.sep, "")
        .replace(/\.hbs$/, "")
        .replace(/\\/g, "/");
      const source = fs.readFileSync(file, "utf-8");
      this.partials.set(name, Handlebars.compile(source));
      Handlebars.registerPartial(name, source);
    }
  }

  private loadTemplates(): void {
    const files = this.readDirRecursive(this.templateDir);
    for (const file of files) {
      if (file.includes(path.sep + "partials" + path.sep)) continue;
      const name = file
        .replace(this.templateDir + path.sep, "")
        .replace(/\.hbs$/, "")
        .replace(/\\/g, "/");
      const source = fs.readFileSync(file, "utf-8");
      this.templates.set(name, Handlebars.compile(source));
      this.rawTemplates.set(name, source);
    }
  }

  private readDirRecursive(dir: string): string[] {
    const results: string[] = [];
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        results.push(...this.readDirRecursive(fullPath));
      } else if (entry.name.endsWith(".hbs")) {
        results.push(fullPath);
      }
    }
    return results;
  }

  getTemplate(name: string): Handlebars.TemplateDelegate | undefined {
    return this.templates.get(name);
  }

  render(name: string, context: TemplateContext): string {
    const template = this.templates.get(name);
    if (!template) {
      throw new Error(`Template not found: ${name}`);
    }

    const renderedContent = template(context);

    const layoutName = (context.page as Record<string, unknown>)?.["layout"] as string | undefined;
    const layout = layoutName || this.defaultLayout;

    if (layout && layout !== name && this.templates.has(layout)) {
      const layoutTemplate = this.templates.get(layout)!;
      return layoutTemplate({ ...context, content: renderedContent });
    }

    return renderedContent;
  }

  hasTemplate(name: string): boolean {
    return this.templates.has(name);
  }
}

import { Feed } from "feed";
import * as fs from "fs";
import * as path from "path";
import { Page } from "./types";

export function generateRss(pages: Page[], siteTitle: string, siteUrl: string, outputDir: string, feedPath?: string): void {
  const feed = new Feed({
    title: siteTitle,
    description: `Latest posts from ${siteTitle}`,
    id: siteUrl,
    link: siteUrl,
    language: "en",
    updated: new Date(),
    generator: "triton",
    feedLinks: {
      rss2: `${siteUrl}/rss.xml`,
    },
  });

  for (const page of pages) {
    feed.addItem({
      title: page.frontmatter.title,
      id: `${siteUrl}${page.url}`,
      link: `${siteUrl}${page.url}`,
      description: page.html.substring(0, 500),
      content: page.html,
      date: page.frontmatter.date ?? new Date(),
    });
  }

  const outputPath = path.join(outputDir, feedPath ?? "rss.xml");
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, feed.rss2());
}

import * as fs from "fs";
import * as path from "path";
import { GeneratorConfig, Page, TagIndex } from "./types";
import { parseFrontmatter, isPublished, pageUrl, sortByDate } from "./frontmatter";
import { renderMarkdown } from "./markdown";
import { TemplateEngine } from "./templates";
import { generateRss } from "./rss";

export class Generator {
  private config: GeneratorConfig;
  private engine: TemplateEngine;

  constructor(config: GeneratorConfig) {
    this.config = config;
    this.engine = new TemplateEngine(config.templateDir);
  }

  build(): Page[] {
    this.engine.load();

    this.prepareOutput();

    const pages = this.collectPages();
    const published = pages.filter((p) => isPublished(p.frontmatter)).sort(sortByDate);

    this.renderPages(published);
    this.copyAssets();

    const tags = this.collectTags(published);
    this.renderTagIndexes(tags, published);

    if (published.length > 0) {
      generateRss(
        published,
        this.config.siteTitle,
        this.config.siteUrl,
        this.config.outputDir,
      );
    }

    return published;
  }

  private prepareOutput(): void {
    if (fs.existsSync(this.config.outputDir)) {
      fs.rmSync(this.config.outputDir, { recursive: true, force: true });
    }
    fs.mkdirSync(this.config.outputDir, { recursive: true });
  }

  private collectPages(): Page[] {
    const pages: Page[] = [];
    this.walkDir(this.config.sourceDir, "", pages);
    return pages;
  }

  private walkDir(dir: string, relativePath: string, pages: Page[]): void {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      const relPath = relativePath ? path.join(relativePath, entry.name) : entry.name;

      if (entry.isDirectory()) {
        this.walkDir(fullPath, relPath, pages);
      } else if (entry.name.endsWith(".md")) {
        const raw = fs.readFileSync(fullPath, "utf-8");
        const { frontmatter, content } = parseFrontmatter(raw, fullPath);
        const html = renderMarkdown(content);
        const url = pageUrl(relPath);

        pages.push({
          path: relPath,
          url,
          frontmatter,
          content,
          html,
          raw,
        });
      }
    }
  }

  private renderPages(pages: Page[]): void {
    const siteContext = {
      title: this.config.siteTitle,
      url: this.config.siteUrl,
      pages: pages.map((p) => ({
        title: p.frontmatter.title,
        url: p.url,
        date: p.frontmatter.date,
        tags: p.frontmatter.tags,
        draft: p.frontmatter.draft,
      })),
      tags: [],
    };

    const pageTemplate = "page";
    const postTemplate = "post";
    const usedTemplate = this.engine.hasTemplate(postTemplate) ? postTemplate : pageTemplate;

    for (const page of pages) {
      const context = {
        page: {
          title: page.frontmatter.title,
          date: page.frontmatter.date,
          tags: page.frontmatter.tags,
          layout: page.frontmatter["layout"] as string | undefined,
        },
        site: siteContext,
        content: page.html,
        pages: siteContext.pages,
      };

      let html: string;
      try {
        html = this.engine.render(usedTemplate, context);
      } catch {
        html = this.engine.render(pageTemplate, context);
      }

      const outPath = path.join(this.config.outputDir, page.url.replace(/^\//, ""));
      fs.mkdirSync(path.dirname(outPath), { recursive: true });
      fs.writeFileSync(outPath, html);
    }

    const indexTemplate = "index";
    if (this.engine.hasTemplate(indexTemplate)) {
      const context = {
        page: { title: this.config.siteTitle },
        site: siteContext,
        pages: siteContext.pages,
        content: "",
      };
      const html = this.engine.render(indexTemplate, context);
      const outPath = path.join(this.config.outputDir, "index.html");
      fs.writeFileSync(outPath, html);
    }
  }

  private collectTags(pages: Page[]): TagIndex[] {
    const tagMap = new Map<string, Page[]>();
    for (const page of pages) {
      for (const tag of page.frontmatter.tags ?? []) {
        const tagKey = tag.toLowerCase();
        if (!tagMap.has(tagKey)) {
          tagMap.set(tagKey, []);
        }
        tagMap.get(tagKey)!.push(page);
      }
    }

    return Array.from(tagMap.entries())
      .map(([tag, tagPages]) => ({ tag, pages: tagPages.sort(sortByDate) }))
      .sort((a, b) => a.tag.localeCompare(b.tag));
  }

  private renderTagIndexes(tags: TagIndex[], allPages: Page[]): void {
    const tagTemplate = "tag";
    if (!this.engine.hasTemplate(tagTemplate)) {
      return;
    }

    const tagsDir = path.join(this.config.outputDir, "tags");
    fs.mkdirSync(tagsDir, { recursive: true });

    const siteContext = {
      title: this.config.siteTitle,
      url: this.config.siteUrl,
      pages: allPages.map((p) => ({
        title: p.frontmatter.title,
        url: p.url,
        date: p.frontmatter.date,
        tags: p.frontmatter.tags,
        draft: p.frontmatter.draft,
      })),
      tags: tags.map((t) => ({ tag: t.tag, count: t.pages.length })),
    };

    for (const tagIndex of tags) {
      const context = {
        page: { title: `Tag: ${tagIndex.tag}` },
        site: siteContext,
        tag: tagIndex.tag,
        pages: tagIndex.pages.map((p) => ({
          title: p.frontmatter.title,
          url: p.url,
          date: p.frontmatter.date,
          tags: p.frontmatter.tags,
        })),
        tags: siteContext.tags,
        content: "",
      };

      const html = this.engine.render(tagTemplate, context);
      const outPath = path.join(tagsDir, `${tagIndex.tag}.html`);
      fs.writeFileSync(outPath, html);
    }
  }

  private copyAssets(): void {
    const assetsDir = path.join(this.config.sourceDir, "assets");
    if (fs.existsSync(assetsDir)) {
      this.copyDir(assetsDir, this.config.outputDir);
    }
  }

  private copyDir(src: string, dest: string): void {
    fs.mkdirSync(dest, { recursive: true });
    const entries = fs.readdirSync(src, { withFileTypes: true });
    for (const entry of entries) {
      const srcPath = path.join(src, entry.name);
      const destPath = path.join(dest, entry.name);
      if (entry.isDirectory()) {
        this.copyDir(srcPath, destPath);
      } else {
        fs.copyFileSync(srcPath, destPath);
      }
    }
  }
}

import * as http from "http";
import * as fs from "fs";
import * as path from "path";
import { WebSocketServer, WebSocket } from "ws";

const LIVE_RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
  ws.onclose = function() {
    console.log('[live-reload] disconnected, retrying in 1s...');
    setTimeout(function() { location.reload(); }, 1000);
  };
})();
</script>
`;

const mimeTypes: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".xml": "application/xml",
};

export function startServer(port: number, outputDir: string): { server: http.Server; reload: () => void } {
  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    const filePath = url === "/" ? "/index.html" : url;

    const fullPath = path.join(outputDir, filePath);
    const ext = path.extname(fullPath).toLowerCase();

    if (!fs.existsSync(fullPath) || fs.statSync(fullPath).isDirectory()) {
      const indexPath = path.join(fullPath, "index.html");
      if (fs.existsSync(indexPath)) {
        serveFile(indexPath, ".html", res);
        return;
      }
      res.writeHead(404);
      res.end("Not Found");
      return;
    }

    serveFile(fullPath, ext, res);
  });

  const wss = new WebSocketServer({ server });
  const clients: Set<WebSocket> = new Set();

  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  function serveFile(filePath: string, ext: string, res: http.ServerResponse): void {
    const mime = mimeTypes[ext] || "application/octet-stream";
    let content = fs.readFileSync(filePath, "utf-8");

    if (ext === ".html") {
      content = content.replace("</body>", `${LIVE_RELOAD_SCRIPT}</body>`);
    }

    res.writeHead(200, { "Content-Type": mime });
    res.end(content);
  }

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });

  return {
    server,
    reload() {
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send("reload");
        }
      }
    },
  };
}

import chokidar from "chokidar";
import { Generator } from "./generator";
import { GeneratorConfig } from "./types";

export function watch(config: GeneratorConfig, onRebuild: () => void): () => void {
  const generator = new Generator(config);

  const watcher = chokidar.watch(
    [config.sourceDir, config.templateDir],
    {
      ignoreInitial: true,
      ignored: [
        /(^|[\/\\])\../,
        "**/node_modules/**",
      ],
    },
  );

  let rebuildTimer: NodeJS.Timeout | null = null;

  function rebuild(): void {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => {
      try {
        generator.build();
        console.log("[watcher] Site rebuilt");
        onRebuild();
      } catch (err) {
        console.error("[watcher] Build error:", err);
      }
    }, 300);
  }

  watcher.on("add", rebuild);
  watcher.on("change", rebuild);
  watcher.on("unlink", rebuild);

  return () => {
    watcher.close();
  };
}

#!/usr/bin/env node

import { Command } from "commander";
import * as path from "path";
import { Generator } from "./generator";
import { GeneratorConfig } from "./types";
import { startServer } from "./server";
import { watch } from "./watcher";

const program = new Command();

program
  .name("triton")
  .description("Static site generator")
  .version("1.0.0")
  .option("-s, --source <dir>", "Source directory of Markdown files", "source")
  .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "Output directory for generated HTML", "public")
  .option("--title <title>", "Site title", "My Site")
  .option("--url <url>", "Site URL", "http://localhost:3000")
  .option("-d, --dev", "Start development server with live reload", false)
  .option("-p, --port <port>", "Dev server port", "3000")
  .action((options) => {
    const config: GeneratorConfig = {
      sourceDir: path.resolve(options.source),
      templateDir: path.resolve(options.templates),
      outputDir: path.resolve(options.output),
      siteTitle: options.title,
      siteUrl: options.url,
      dev: options.dev,
      port: parseInt(options.port, 10),
    };

    const generator = new Generator(config);
    generator.build();

    if (config.dev) {
      const { server, reload } = startServer(config.port, config.outputDir);

      const stopWatch = watch(config, reload);

      process.on("SIGINT", () => {
        stopWatch();
        server.close();
        process.exit(0);
      });

      process.on("SIGTERM", () => {
        stopWatch();
        server.close();
        process.exit(0);
      });
    }
  });

program.parse(process.argv);

