import { describe, it, expect } from "vitest";
import { parseFrontmatter, isPublished, pageUrl, sortByDate } from "../src/frontmatter";
import { Page } from "../src/types";

describe("parseFrontmatter", () => {
  it("parses title from YAML frontmatter", () => {
    const raw = `---
title: Test Post
---
Content here.`;

    const { frontmatter, content } = parseFrontmatter(raw, "test.md");
    expect(frontmatter.title).toBe("Test Post");
    expect(content.trim()).toBe("Content here.");
  });

  it("parses date as Date object", () => {
    const raw = `---
title: Post
date: 2025-06-15
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter.date).toBeInstanceOf(Date);
    expect(frontmatter.date!.getFullYear()).toBe(2025);
    expect(frontmatter.date!.getMonth()).toBe(5);
    expect(frontmatter.date!.getDate()).toBe(15);
  });

  it("parses tags array", () => {
    const raw = `---
title: Post
tags:
  - js
  - ts
  - rust
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter.tags).toEqual(["js", "ts", "rust"]);
  });

  it("parses comma-separated tags string", () => {
    const raw = `---
title: Post
tags: js, ts, rust
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter.tags).toEqual(["js", "ts", "rust"]);
  });

  it("parses draft flag", () => {
    const raw = `---
title: Draft
draft: true
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "draft.md");
    expect(frontmatter.draft).toBe(true);
  });

  it("defaults draft to falsy when not set", () => {
    const raw = `---
title: Post
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter.draft).toBeFalsy();
  });

  it("defaults tags to empty array", () => {
    const raw = `---
title: Post
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter.tags).toEqual([]);
  });

  it("handles missing all optional fields", () => {
    const raw = "# Just markdown\n\nNo frontmatter at all.";

    const { frontmatter, content } = parseFrontmatter(raw, "plain.md");
    expect(frontmatter.title).toBeUndefined();
    expect(frontmatter.date).toBeUndefined();
    expect(frontmatter.tags).toEqual([]);
    expect(frontmatter.draft).toBeFalsy();
    expect(content).toContain("Just markdown");
  });

  it("handles custom frontmatter fields", () => {
    const raw = `---
title: Post
layout: custom
author: Alice
---
Content`;

    const { frontmatter } = parseFrontmatter(raw, "post.md");
    expect(frontmatter["layout"]).toBe("custom");
    expect(frontmatter["author"]).toBe("Alice");
  });
});

describe("isPublished", () => {
  it("returns true for non-draft", () => {
    expect(isPublished({ draft: false })).toBe(true);
    expect(isPublished({})).toBe(true);
  });

  it("returns false for drafts", () => {
    expect(isPublished({ draft: true })).toBe(false);
  });
});

describe("pageUrl", () => {
  it("converts .md to .html", () => {
    expect(pageUrl("hello.md")).toBe("/hello.html");
  });

  it("handles nested paths", () => {
    expect(pageUrl("posts/hello.md")).toBe("/posts/hello.html");
  });

  it("preserves leading slash", () => {
    expect(pageUrl("/posts/hello.md")).toBe("/posts/hello.html");
  });

  it("converts index.md to directory path", () => {
    expect(pageUrl("posts/index.md")).toBe("/posts/");
  });

  it("does not convert root index.md", () => {
    const result = pageUrl("index.md");
    expect(result).toBe("/index.html");
  });
});

describe("sortByDate", () => {
  it("sorts newest first", () => {
    const pages: Page[] = [
      {
        path: "a.md", url: "/a.html",
        frontmatter: { title: "A", date: new Date("2025-01-01") },
        content: "", html: "", raw: "",
      },
      {
        path: "b.md", url: "/b.html",
        frontmatter: { title: "B", date: new Date("2025-06-01") },
        content: "", html: "", raw: "",
      },
      {
        path: "c.md", url: "/c.html",
        frontmatter: { title: "C", date: new Date("2024-12-01") },
        content: "", html: "", raw: "",
      },
    ];

    const sorted = [...pages].sort(sortByDate);
    expect(sorted[0].frontmatter.title).toBe("B");
    expect(sorted[1].frontmatter.title).toBe("A");
    expect(sorted[2].frontmatter.title).toBe("C");
  });

  it("puts undated entries last", () => {
    const pages: Page[] = [
      { path: "a.md", url: "/a.html", frontmatter: { title: "A", date: new Date("2025-01-01") }, content: "", html: "", raw: "" },
      { path: "b.md", url: "/b.html", frontmatter: { title: "B" }, content: "", html: "", raw: "" },
    ];

    const sorted = [...pages].sort(sortByDate);
    expect(sorted[0].frontmatter.title).toBe("A");
    expect(sorted[1].frontmatter.title).toBe("B");
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import { TemplateEngine } from "../src/templates";

describe("TemplateEngine", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "triton-templates-"));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function writeTemplate(name: string, content: string): void {
    const fullPath = path.join(tmpDir, name);
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    fs.writeFileSync(fullPath, content);
  }

  it("loads and renders a template", () => {
    writeTemplate("page.hbs", "<h1>{{page.title}}</h1><div>{{{content}}}</div>");

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("page", {
      page: { title: "Hello" },
      content: "<p>World</p>",
    });

    expect(html).toContain("<h1>Hello</h1>");
    expect(html).toContain("<p>World</p>");
  });

  it("wraps content with a layout template", () => {
    writeTemplate("default.hbs", '<html><body><main>{{{content}}}</main></body></html>');
    writeTemplate("page.hbs", '<article>{{{content}}}</article>');

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("page", {
      page: { title: "Test" },
      content: "<p>Body</p>",
    });

    expect(html).toContain("<html>");
    expect(html).toContain("<article>");
    expect(html).toContain("<p>Body</p>");
    expect(html).toContain("</html>");
  });

  it("respects custom layout from page frontmatter", () => {
    writeTemplate("default.hbs", '<html>{{{content}}}</html>');
    writeTemplate("custom.hbs", '<div class="custom">{{{content}}}</div>');
    writeTemplate("page.hbs", '<p>{{{content}}}</p>');

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("page", {
      page: { title: "Test", layout: "custom" },
      content: "Hello",
    });

    expect(html).toContain('<div class="custom">');
    expect(html).not.toContain("<html>");
  });

  it("loads and uses partials", () => {
    writeTemplate("partials/header.hbs", "<header>{{site.title}}</header>");
    writeTemplate("default.hbs", "<html>{{> header}}{{{content}}}</html>");
    writeTemplate("page.hbs", "{{{content}}}");

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("page", {
      page: { title: "Test" },
      site: { title: "My Site" },
      content: "<p>Hi</p>",
    });

    expect(html).toContain("<header>My Site</header>");
  });

  it("throws for missing template", () => {
    const engine = new TemplateEngine(tmpDir);
    engine.load();

    expect(() => engine.render("nonexistent", {})).toThrow("Template not found");
  });

  it("handles empty template directory gracefully", () => {
    const engine = new TemplateEngine("/nonexistent/path");
    engine.load();
    expect(engine.hasTemplate("anything")).toBe(false);
  });

  it("supports Handlebars each helper", () => {
    writeTemplate("index.hbs", "<ul>{{#each pages}}<li>{{title}}</li>{{/each}}</ul>");

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("index", {
      pages: [{ title: "A" }, { title: "B" }],
    });

    expect(html).toContain("<li>A</li>");
    expect(html).toContain("<li>B</li>");
  });

  it("supports nested partial directories", () => {
    writeTemplate("partials/ui/button.hbs", '<button>{{text}}</button>');
    writeTemplate("default.hbs", "{{> ui/button}}{{{content}}}");
    writeTemplate("page.hbs", "x");

    const engine = new TemplateEngine(tmpDir);
    engine.load();

    const html = engine.render("page", {
      page: { title: "T" },
      text: "Click",
      content: "",
    });

    expect(html).toContain("<button>Click</button>");
  });
});

